export type WorldChoiceView={id:string;key:string;kind:'travel'|'explore'|'language'|'conversation'|'food'|'relationship'|'tradeoff'|'work'|'relocate';title:string;body:string;description:string;available:boolean;reason:string;preview:WorldPreview;previewText:string[];outcome:string;time:number;cost:number;actorId?:string;spot?:string;stage?:string};
type WorldPlayer=Player&{world?:WorldState};
type Proposal={shelteredExploration?:boolean;climateEffect?:{joyUsed:number;recoveryUsed:number;exposureUsed:number;requiredEnergy:number};key:string;kind:WorldChoiceView['kind'];title:string;body:string;outcome:string;change?:Partial<WorldPreview>;requirement?:string;companionStatus?:WorldState['companionStatus'];residentId?:string;opportunityId?:string};
const state=(p:Player)=>(p as WorldPlayer).world;
const clamp=(n:number,min=0,max=100)=>Math.max(min,Math.min(max,n));
const emptyPlaces=():Record<RegionId,string[]>=>({alder:[],saffron:[],glasssteppe:[],pelagia:[],embermesa:[]});
const emptyLocaleHistory=(arrivals=0):WorldLocaleHistory=>({arrivals,actions:0,departures:[],completedOpportunities:[]});
function note(p:Player,g:Pick<Game,'round'>,title:string,text:string){const w=state(p)!;w.journal.push({week:g.round,region:w.region,title,text});}
function discover(p:Player,g:Game,id:RegionId,text:string){const w=state(p)!;if(w.discoveredRegions.includes(id))return;w.discoveredRegions.push(id);note(p,g,`${regionDefinitions[id].name} is on your map`,text);w.revision++;}
function reveal(p:Player,g:Game,place:string,text:string){const w=state(p)!;if(w.discoveredPlacesByRegion[w.region].includes(place)||sharedVenueReason(g,w.region,place)!=='')return;w.discoveredPlacesByRegion[w.region].push(place);note(p,g,`${place} discovered`,text);w.revision++;}
const copyReturn=(change:WorldReturnChange):WorldReturnChange=>({...change,opportunity:{...change.opportunity}});
function historyFor(w:WorldState,id:RegionId):WorldLocaleHistory{return w.localeHistory[id];}
function mutableHistory(w:WorldState,id:RegionId){return w.localeHistory[id];}
/** Initialize a new player after initializeLifePlayer; preserve existing current state. */
export function initializeWorldPlayer(p:Player){if(state(p)||!p.life)return;const places=emptyPlaces();places.alder=[...essentialPlaces];(p as WorldPlayer).world={version:1,region:'alder',discoveredRegions:['alder'],discoveredPlacesByRegion:places,languageFamiliarity:{alder:3,saffron:0,glasssteppe:0,pelagia:0,embermesa:2},companionBond:0,companionStatus:'unmet',journal:[{week:1,region:'alder',title:'A small map, a new beginning',text:'You know home, work, the park, the corner café and the community room. Walk, talk and let the rest of Alder Quay find you.'}],revision:0,lastWeek:1,actionCounts:{},acceptedChoices:[],localBonds:{},localTalkWeeks:{},localeHistory:{alder:emptyLocaleHistory(1),saffron:emptyLocaleHistory(),glasssteppe:emptyLocaleHistory(),pelagia:emptyLocaleHistory(),embermesa:emptyLocaleHistory()}};}
/** A game supplies the shared closures; player-only map reads use discovered places. */
export function visiblePlaces(p:Player,g?:Game):string[]{if(g)return storyVisiblePlaces(p,g);const w=state(p)!;return worldPlaceIds.filter(v=>essentialPlaces.includes(v)||w.discoveredPlacesByRegion[w.region].includes(v));}
function syncRoutes(g:Game,p:Player){
 const w=state(p)!;
 for(const id of regionIds)if(g.round>=regionDefinitions[id].unlockWeek)discover(p,g,id,`The ${regionDefinitions[id].name} route is now open. You can choose to travel; nothing makes you leave.`);
 const flags=p.life?.flags??[];
 if(g.round>=2&&flags.some(f=>['unexpected_calling','first_workshop','independent_work','invested_in_calling','shared_credit'].includes(f)))discover(p,g,'glasssteppe','Your practical work reaches a railway co-op in Glasssteppe. A real introduction opens the highland route earlier than the regular service.');
 if(g.round>=2&&flags.some(f=>['one_day_studio','independent_work','first_independent_client','shared_toolkit'].includes(f)))discover(p,g,'embermesa','A repair-shop owner in Ember Mesa hears about your practical work and offers a railway introduction a month before the usual route.');
 const eli=p.life?.relationships.eli;
 if(g.round>=2&&flags.includes('food_coop')&&eli&&!eli.rivalry&&(eli.support||eli.trust>=1))discover(p,g,'pelagia','Eli’s food co-op introduces you to Pelagia’s harbor growers. Their working-boat route opens before the public ferry season.');
 if(g.round>=2&&w.companionStatus==='unmet')w.companionStatus='invited';
}
/** Apply after a successful base action or life choice, never as part of a read/preview. */
export function afterWorldAction(g:Game,p:Player,id:string){afterStoryWorldAction(g,p,id);}
/** Shared regional development advances once per month. */
export function beginWorldWeek(g:Game){beginSharedWorldWeek(g);}
function effective(p:Player,change:Partial<WorldPreview>={}):WorldPreview{const w=state(p)!;const destination=change.region??w.region;return{cash:change.cash||0,hours:clamp(p.hours+(change.hours??0),0,6)-p.hours,energy:clamp(p.energy+(change.energy??0))-p.energy,joy:clamp(p.joy+(change.joy??0))-p.joy,social:Math.max(0,p.social+(change.social??0))-p.social,language:clamp(w.languageFamiliarity[w.region]+(change.language??0),0,3)-w.languageFamiliarity[w.region],companionBond:clamp(w.companionBond+(change.companionBond??0),0,5)-w.companionBond,localBonds:Object.fromEntries(Object.entries(change.localBonds??{}).map(([id,delta])=>[id,clamp((w.localBonds?.[id]??0)+delta,0,3)-(w.localBonds?.[id]??0)])),...(change.region?{region:change.region}:{}),revealPlaces:(change.revealPlaces??[]).filter(v=>!w.discoveredPlacesByRegion[destination].includes(v)),closePlaces:[],discoverRegions:(change.discoverRegions??[]).filter(v=>!w.discoveredRegions.includes(v))};}
/** Density changes this deliberate exploration activity, never free map navigation. */
function settlementProposals<T extends Proposal>(p:Player,g:Game,items:T[]):T[]{
 const profile=regionalLifeProfile(p,g);if(!profile)return items;
 return items.map(c=>{
  if(c.key!=='explore')return c;
  const places=storyHiddenPlaces(p,g).slice(0,profile.discoveries);
  const names=places.map(place=>worldPlaceName(p,place,g));
  const body=places.length?`1 time, $0. ${profile.exploreText} Find ${names.join(' and ')}. You can always use free local navigation to reach places already on your map.`:'You know the open services here; no exploration is needed.';
  return{...c,shelteredExploration:profile.sheltered,title:places.length?profile.exploreTitle:'Your district is mapped',body,outcome:places.length?`${profile.exploreText} You add ${names.join(' and ')} to your map.`:c.outcome,change:{...c.change,energy:profile.recovery,joy:profile.joy,revealPlaces:places},requirement:places.length?'':'Every open venue here is discovered'};
 });
}
/** Explicit outdoor choices only: indoor jobs, conversations and money rules stay untouched. */
function climateProposals<T extends Proposal>(p:Player,g:Game,items:T[]):T[]{
 items=settlementProposals(p,g,items);
 if(!getWeather(g,p)?.climate)return items;
 return items.map(c=>{
  const base={joy:c.change?.joy||0,energy:c.change?.energy||0};
  const travel=c.kind==='travel'&&c.change?.region?climateTravelEffect(p,g,c.change.region):null;
  const effect=travel??((c.key==='explore'&&!c.shelteredExploration)||c.key==='region_rest'?climateEffect(p,{id:c.key==='region_rest'?'rest':'explore'},g,base):null);
  if(!effect)return c;
  const joy=effect.joy;
  const energy=clamp(p.energy+base.energy)-p.energy+effect.energy;
  return{...c,climateEffect:effect,change:{...c.change,energy,joy:clamp(p.joy+base.joy)-p.joy+joy},body:`${c.body} ${effect.storySummary}`,outcome:`${c.outcome} ${effect.storySummary}`};
 });
}
function choiceReason(p:Player,g:Game,c:Proposal){if(g.status!=='playing')return'The game is not running';if(g.players[g.turn]!==p)return'It is another player’s turn';if(c.requirement)return c.requirement;if(c.climateEffect&&p.energy<c.climateEffect.requiredEnergy)return`Needs ${c.climateEffect.requiredEnergy} energy including weather; rest at home first`;if(p.hours<-(c.change?.hours??0))return`Needs ${-(c.change?.hours??0)} priority blocks this month`;if((c.change?.cash??0)<0&&p.cash<-(c.change?.cash??0))return`Needs $${-(c.change?.cash??0)} available cash`;return'';}
function effectText(e:WorldPreview){const text:string[]=[];for(const [key,label] of [['hours','time'],['cash','cash'],['energy','energy'],['joy','happiness'],['social','connections'],['language','language'],['companionBond','Neri bond']] as const){const n=e[key];if(n)text.push(`${n>0?'+':''}${n} ${label}`);}for(const [id,n]of Object.entries(e.localBonds))if(n)text.push(`+${n} bond with ${regionIds.flatMap(r=>regionDefinitions[r].residents).find(r=>r.id===id)?.name??id}`);if(e.region)text.push(`Arrive in ${regionDefinitions[e.region].name}`);if(e.revealPlaces.length)text.push(`Discover: ${e.revealPlaces.join(', ')}`);if(e.closePlaces.length)text.push(`Permanently close here: ${e.closePlaces.join(', ')}`);if(e.discoverRegions.length)text.push(`New routes: ${e.discoverRegions.map(id=>regionDefinitions[id].name).join(', ')}`);return text;}
export function worldChoices(p:Player,g:Game):WorldChoiceView[]{return [...storyWorldChoices(p,g),...sharedWorldChoices(p,g)];}
export function resolveWorldChoice(g:Game,p:Player,id:string):WorldJournalEntry{return resolveStoryWorldChoice(g,p,id);}
export function worldView(p:Player,g:Game){return storyWorldView(p,g);}
/** Regional display names never replace stable backend place IDs. */
export function worldPlaceName(p:Player,place:string,g?:Game):string{const region=state(p)!.region;return(g?getSharedVenueState(g,region,place)?.name:undefined)??regionDefinitions[region].placeNames[place]??place;}

export type SharedVenueState={id:string;place:string;status:'open'|'repurposed'|'closed';name:string;description:string;reason:string;source:'story'|'regional';week:number;use?:WorldVenueUse};
export type SharedVenueChange=Omit<SharedVenueState,'name'|'week'>&{region:RegionId;name?:string;week?:number};
export type SharedRegionState={revision:number;venues:Record<string,SharedVenueState>;changes:WorldReturnChange[];contribution:number;contributionKeys:string[];development:number};
export type SharedWorldState={version:1;revision:number;lastWeek:number;regions:Record<RegionId,SharedRegionState>;appliedChanges:string[]};
export type NeriStory={stage:'unmet'|'introduced'|'planned'|'discussed'|'committed'|'fulfilled'|'declined';lastSceneWeek:number;plan?:'coast'|'home';challenge?:'distance'|'visit'|'friendship';commitment?:'partner'|'friendship';posting:'not-yet'|'accepted';scenes:{week:number;key:string;text:string}[]};
export type StoryWorldPersonal={version:1;homeRegion:RegionId;relocatedWeek?:number;localChoices:Record<string,'help'|'listen'>;localTalks:Record<string,number>;regionalWorkWeeks:Partial<Record<RegionId,number>>;seenRegionRevision:Partial<Record<RegionId,number>>;lastReturnNarrative?:string;journey:RegionId[];neri:NeriStory};
type StoryGame=Game&{sharedWorld?:SharedWorldState};
const sharedWorld=(g:Game)=>(g as StoryGame).sharedWorld;
const personal=(p:Player)=>state(p)!.story!;
/** Initialize shared state and each newly-created player. */
export function initializeSharedWorld(g:Game){
 const sg=g as StoryGame;
 sg.sharedWorld??={version:1,revision:0,lastWeek:g.round,regions:Object.fromEntries(regionIds.map(id=>[id,{revision:0,venues:{},changes:[],contribution:0,contributionKeys:[],development:0}])) as unknown as Record<RegionId,SharedRegionState>,appliedChanges:[]};
 for(const p of g.players)initializeStoryWorldPlayer(g,p);
}
/** Initialize a joining player in an already initialized shared world. */
export function initializeStoryWorldPlayer(g:Game,p:Player){
 if(!sharedWorld(g)||!state(p)||state(p)!.story)return;
 state(p)!.story={version:1,homeRegion:'alder',localChoices:{},localTalks:{},regionalWorkWeeks:{},seenRegionRevision:{alder:sharedWorld(g)!.regions.alder.revision},journey:['alder'],neri:{stage:'unmet',lastSceneWeek:0,posting:'not-yet',scenes:[]}};
}
export function getSharedVenueState(g:Game,region:RegionId,place:string):SharedVenueState|undefined{const venue=sharedWorld(g)?.regions[region]?.venues[place];return venue?{...venue}:undefined;}
export function sharedVenueReason(g:Game,region:RegionId,place:string):string{const venue=getSharedVenueState(g,region,place);return venue?.status==='closed'?venue.reason:'';}
/** Server mutation, idempotent by change.id. Regional development cannot overwrite an authored story venue. */
export function applySharedVenueChange(g:Game,change:SharedVenueChange):boolean{
 const sw=sharedWorld(g);if(!sw)return false;
 if(!regionIds.includes(change.region)||!worldPlaceIds.includes(change.place as typeof worldPlaceIds[number]))throw Error('Unknown shared venue');
 if(change.status==='closed'&&essentialPlaces.includes(change.place))throw Error('Home, work, rest, café and community must remain available');
 if(sw.appliedChanges.includes(change.id))return false;
 const r=sw.regions[change.region],prior=r.venues[change.place];if(prior?.source==='story'&&change.source==='regional')return false;
 r.venues[change.place]={id:change.id,place:change.place,status:change.status,name:change.name??prior?.name??regionDefinitions[change.region].placeNames[change.place],description:change.description,reason:change.reason,source:change.source,week:change.week??g.round,...(change.use?{use:change.use}:{})};
 r.revision++;sw.revision++;sw.appliedChanges.push(change.id);
 for(const p of g.players){state(p)!.revision++;if(state(p)!.region===change.region&&change.status==='closed'&&p.place===change.place){p.place='APARTMENTS';g.log.unshift(`${p.name}: ${r.venues[change.place].name} has closed. You return to a safe home space without spending time. ${change.reason}`);g.log=g.log.slice(0,32);}}
 return true;
}
function storyVisiblePlaces(p:Player,g:Game){const w=state(p)!;return worldPlaceIds.filter(place=>(essentialPlaces.includes(place)||w.discoveredPlacesByRegion[w.region].includes(place))&&getSharedVenueState(g,w.region,place)?.status!=='closed');}
function storyHiddenPlaces(p:Player,g:Game){const w=state(p)!;return discoveryOrder[w.region].filter(place=>!w.discoveredPlacesByRegion[w.region].includes(place)&&getSharedVenueState(g,w.region,place)?.status!=='closed');}

