function addRegionalContribution(g:Game,p:Player,key:string){const sw=sharedWorld(g);if(!sw)return;const r=sw.regions[state(p)!.region],token=`${p.id}:${g.round}:${key}`;if(r.contributionKeys.includes(token))return;r.contributionKeys.push(token);r.contribution++;}
/** Venue contracts retain the existing regional-work contribution, once/month. */
export function afterCareerWorldWork(g:Game,p:Player,target:string){afterStoryWorldAction(g,p,'work');if(target==='r.local'){personal(p).regionalWorkWeeks[state(p)!.region]=g.round;addRegionalContribution(g,p,'regional-work');}}
function developRegions(g:Game){
 const sw=sharedWorld(g);if(!sw)return;
 for(const region of regionIds){const r=sw.regions[region];while(r.development<3){const index=r.development,due=3+index*2,earlier=r.contribution>=3*(index+1);if(g.round<due-(earlier?1:0))break;
 const program=regionalPrograms[region][index],definition=regionDefinitions[region],resident=definition.residents.find(v=>v.id===program.residentId)!;
 const reason=storyText(`Week ${g.round}: ${earlier&&g.round<due?'local contributions brought the planned opening forward':'neighbors completed their scheduled work'}.`);
 const applied=applySharedVenueChange(g,{id:`regional:${region}:${index+1}`,region,place:program.place,status:'repurposed',name:program.name,description:program.description,reason,source:'regional',use:program.use});r.development++;
 if(!applied)continue;
 const cash=60+index*10,opportunity:WorldReturnOpportunity={id:`${region}-chapter-${index+1}`,title:program.job,body:`1 time, $0. A one-time neighborhood task with a $${cash} thank-you stipend, +5 happiness, +1 connection and a local bond.`,cash,joy:5,social:1,residentId:resident.id,place:program.place};
 r.changes.push({region,sequence:index+1,week:g.round,place:program.place,venueName:program.name,venueDescription:program.description,venueUse:program.use,change:'repurposed',residentId:resident.id,residentName:resident.name,residentCircumstance:program.circumstance,welcome:`${resident.name} has news of a life that kept moving.`,narrative:`${program.description} ${program.circumstance} ${reason}`,opportunity});
 }
 }
}
function syncStoryRoutes(g:Game,p:Player){syncRoutes(g,p);if(g.round>=4)personal(p).neri.posting='accepted';}
function observeRegion(g:Game,p:Player){const w=state(p)!,s=personal(p),r=sharedWorld(g)!.regions[w.region],seen=s.seenRegionRevision[w.region]??0;for(const c of r.changes.filter(c=>c.week<=g.round&&!w.journal.some(v=>v.title===c.venueName))){note(p,g,c.venueName,c.narrative);if(!w.discoveredPlacesByRegion[w.region].includes(c.place))w.discoveredPlacesByRegion[w.region].push(c.place);}if(seen!==r.revision)s.seenRegionRevision[w.region]=r.revision;}
function beginSharedWorldWeek(g:Game){
 if(g.status!=='playing')return;const sw=sharedWorld(g)!;if(sw.lastWeek<g.round){developRegions(g);sw.lastWeek=g.round;}
 for(const p of g.players){const w=state(p)!;if(w.lastWeek>=g.round)continue;w.lastWeek=g.round;for(let i=0;i<2;i++){const place=storyHiddenPlaces(p,g)[0];if(place)reveal(p,g,place,storyText(`Week ${g.round}: a neighbor shows you ${regionDefinitions[w.region].placeNames[place]}.`));}syncStoryRoutes(g,p);observeRegion(g,p);w.revision++;}
}
function afterStoryWorldAction(g:Game,p:Player,id:string){
 const w=state(p)!;w.actionCounts[id]=(w.actionCounts[id]??0)+1;const h=mutableHistory(w,w.region);h.actions++;h.lastAction=id;
 const place=id==='rest'?'LIBRARY':id==='friends'||id==='cafe_break'?'MARKET':id==='volunteer'||id==='community_setup'?'GARDEN':id==='study'||id==='library_learn'?'MAKERSPACE':id.startsWith('work')?'CAREER HUB':null;
 if(place)reveal(p,g,place,`Someone you meet points out ${regionDefinitions[w.region].placeNames[place]}.`);
 if(/garden|volunteer|community_setup|creative_practice/.test(id))addRegionalContribution(g,p,'ordinary-care');
 syncStoryRoutes(g,p);w.revision++;
}

