type StoryProposal=Proposal&{actorId?:string;spot?:string;stage?:string;localDecision?:'help'|'listen';neriStep?:Partial<NeriStory>;homeRegion?:RegionId;contribution?:string};
/** A first introduction can happen at a public desk; specialist work still reveals its own venue.
 * The same ordered venue list powers NPC placement, the Meet button and server choice checks. */
function storyResidentPlaces(p:Player,g:Game,resident:RegionResident):string[]{
 const familyVenue=canonicalFamilyVenue(g.round,resident.id);if(familyVenue)return[familyVenue];
 const publicPlace=resident.places.find(place=>essentialPlaces.includes(place))??(resident.places.includes('MAKERSPACE')?'WORK':resident.places.includes('GARDEN')?'THE PARK':'CORNER CAFÉ');
 const allowed=[...new Set([...resident.places,publicPlace,...(regionalWork[state(p)!.region].resident===resident.id?['WORK']:[])])],visible:string[]=storyVisiblePlaces(p,g);
 const current=allowed.includes(p.place)&&visible.includes(p.place)?p.place:allowed.find(place=>visible.includes(place))??publicPlace;
 return[current,...allowed.filter(place=>place!==current)];
}
