 const developed=sharedWorld(g)!.regions[w.region].changes.filter(c=>c.residentId===resident.id).at(-1);
 const home=s.homeRegion===w.region?' You are sharing the ordinary weeks here now.':historyFor(w,w.region).arrivals>1?' They remember that you came back.':' You can care about this place without promising to stay.';
 const ordinaryFollowup=['','', 'You compare which ordinary routine has become easier since you last spoke.', 'They ask what you had to postpone to make room for something important.', 'The conversation returns to one decision you each made, and what it actually cost.', 'You hear who else helped, including someone you have not met.', 'They ask what should stay small even if the project succeeds.', 'You trade a practical next step each of you can keep after this chapter.'][Math.min(7,g.round-1)];
