 return {key:help?`local_help:${resident.id}`:`talk:${resident.id}`,kind:'conversation',actorId:resident.id,spot:storyResidentPlaces(p,g,resident)[0],stage:talks===0?'A small choice':talks===1?'What your conversation changed':`Week ${g.round}: a life of their own`,title:talks===0?(help?thread.offer:`Listen to ${resident.name}’s plans`):`Catch up with ${resident.name}`,body:`${talks===0?thread.ask:thread.plan} 1 time, $0. ${talks===0&&help?'Make a small, specific contribution.':'Spend a little time together. Friendship never commits you to relocation.'}`,outcome:[talks>=2?`${text} ${ordinaryFollowup}`:text,characterVoiceResponse(resident.id,help?'help':'ask',talks>=2?'support':'smaller-offer')].filter(Boolean).join(' '),change:{hours:-1,joy:talks===0?5:7,social:familiar?1:0,language:familiar===0?1:0,localBonds:{[resident.id]:1},revealPlaces:talks===0?resident.places.filter(v=>!essentialPlaces.includes(v)).slice(0,1):[]},requirement:w.localTalkWeeks?.[resident.id]===g.round?`${resident.name} has plans of their own just now.`:'',residentId:resident.id,...(talks===0?{localDecision:help?'help' as const:'listen' as const}:{}),...(help?{contribution:`resident:${resident.id}`}:{})};
