function returnAcknowledgment(p:Player,g:Game,id:RegionId){
 const w=state(p)!,h=historyFor(w,id);if(!h.arrivals)return null;
 const s=personal(p),r=sharedWorld(g)!.regions[id],away=Math.max(0,g.round-(h.departures.at(-1)?.week??g.round));
 const resident=[...regionDefinitions[id].residents].sort((a,b)=>(w.localBonds?.[b.id]??0)-(w.localBonds?.[a.id]??0))[0],bond=w.localBonds?.[resident.id]??0;
 const welcome=bond>=2?`${resident.name} remembers your last conversation and makes room at the table.`:`${resident.name} notices you are back and asks how the journey went.`;
 const newChanges=r.changes.filter(c=>c.week>(h.departures.at(-1)?.week??0));
 const authoredChanges=r.revision>(s.seenRegionRevision[id]??0)?Object.values(r.venues).filter(v=>v.source==='story'&&v.week>=(h.departures.at(-1)?.week??g.round)).map(v=>v.description):[];
 const scale=away===0?'You have only been away briefly. The same streets are here; coming back still matters.':away===1?'A chapter has passed since you left. There are ordinary updates to catch up on.':`${away} chapters have passed since you left. Your old routines and the neighborhood’s plans have had time to change.`;
 return `${welcome} ${scale}${newChanges.length?' '+newChanges.map(c=>c.venueDescription).join(' '):''}${authoredChanges.length?' '+authoredChanges.join(' '):''}${s.localChoices[resident.id]==='help'?' They remember the practical help you offered.':''}`;
}
