 if(g.status!=='playing')throw Error('The game is not running');if(g.players[g.turn]!==p)throw Error('It is another player’s turn');const w=state(p)!,s=personal(p),previous=w.journal.find(e=>e.choiceId===id);if(previous)return previous;
