 const e=storyChoicePreview(p,g,c),origin=w.region;if(c.climateEffect)consumeClimateEffect(p,g,c.climateEffect);for(const key of ['cash','hours','energy','joy','social'] as const)p[key]+=e[key];w.languageFamiliarity[origin]+=e.language;w.companionBond+=e.companionBond;
 if(e.region){const from=mutableHistory(w,origin);from.departures.push({week:g.round,actions:from.actions,...(from.lastAction?{lastAction:from.lastAction}:{}),bonds:Object.fromEntries(regionDefinitions[origin].residents.map(r=>[r.id,w.localBonds?.[r.id]??0]))});const to=mutableHistory(w,e.region);const returning=to.arrivals>0;to.arrivals++;w.region=e.region;p.place='APARTMENTS';s.journey.push(e.region);s.lastReturnNarrative=returning?storyText(c.outcome):undefined;}else{const h=mutableHistory(w,origin);h.actions++;h.lastAction=c.key;}
 for(const place of e.revealPlaces)if(!w.discoveredPlacesByRegion[w.region].includes(place))w.discoveredPlacesByRegion[w.region].push(place);
 for(const region of e.discoverRegions)if(!w.discoveredRegions.includes(region))w.discoveredRegions.push(region);
 for(const [resident,delta]of Object.entries(e.localBonds)){w.localBonds??={};w.localBonds[resident]=(w.localBonds[resident]??0)+delta;}
 if(c.residentId){w.localTalkWeeks??={};w.localTalkWeeks[c.residentId]=g.round;s.localTalks[c.residentId]=(s.localTalks[c.residentId]??0)+1;if(c.localDecision)s.localChoices[c.residentId]=c.localDecision;}
 if(c.opportunityId)mutableHistory(w,origin).completedOpportunities.push(c.opportunityId);
 if(c.neriStep){Object.assign(s.neri,c.neriStep,{lastSceneWeek:g.round});s.neri.scenes.push({week:g.round,key:c.key,text:storyText(c.outcome)});}
