 const entry:WorldJournalEntry={week:g.round,region:w.region,title:storyText(c.title),text:storyText(c.outcome),choiceId:id,effects:e};w.journal.push(entry);g.log.unshift(`${p.name}: ${entry.title}. ${entry.text}`);g.log=g.log.slice(0,32);return entry;
